import random

class Solution:
  def wiggleSort(self, nums: list[int]) -> None:
    n = len(nums)
    median = self._findKthLargest(nums, (n + 1) // 2)

    def A(i: int):
      return (1 + 2 * i) % (n | 1)

    i = 0
    j = 0
    k = n - 1

    while i <= k:
      if nums[A(i)] > median:
        nums[A(i)], nums[A(j)] = nums[A(j)], nums[A(i)]
        i, j = i + 1, j + 1
      elif nums[A(i)] < median:
        nums[A(i)], nums[A(k)] = nums[A(k)], nums[A(i)]
        k -= 1
      else:
        i += 1

  def _findKthLargest(self, nums: list[int], k: int) -> int:
    target = len(nums) - k
    low, high = 0, len(nums) - 1
    while low <= high:
      pivot = nums[random.randint(low, high)]
      left, scan, right = low, low, high
      while scan <= right:
        if nums[scan] < pivot:
          nums[left], nums[scan] = nums[scan], nums[left]
          left += 1
          scan += 1
        elif nums[scan] > pivot:
          nums[scan], nums[right] = nums[right], nums[scan]
          right -= 1
        else:
          scan += 1
      if target < left:
        high = left - 1
      elif target > right:
        low = right + 1
      else:
        return pivot
    raise ValueError('k outside the input range')

